def esc(s):
 if s is None or (isinstance(s,float) and not np.isfinite(s)):return '--'
 return str(s).replace('\\',r'\textbackslash{}').replace('&',r'\&').replace('%',r'\%').replace('_',r'\_').replace('#',r'\#')
