 s+=''.join(' & '.join(str(v) for v in row)+r'\\'+'\n' for row in rows);s+='\\bottomrule\\end{tabular}\n\\caption{'+caption+'}\\label{'+label+'}\n\\end{table}\n';(out/file).write_text(s)
