# Longtable helper: caption appears after the final segment, never at the top.
def longtable(path,df,caption,label,formats=None):
 cols=list(df.columns);formats=formats or ['p{'+str(round(.92/len(cols),3))+r'\textwidth}']*len(cols);s='\\begin{longtable}{'+''.join(formats)+'}\n\\toprule\n'+' & '.join(esc(c) for c in cols)+r'\\\midrule\endfirsthead'+'\n\\toprule\n'+' & '.join(esc(c) for c in cols)+r'\\\midrule\endhead'+'\n'
 for row in df.itertuples(index=False,name=None):s+=' & '.join(n(v) if isinstance(v,(float,np.floating)) else esc(v) for v in row)+r'\\'+'\n'
 s+='\\bottomrule\n\\caption{'+caption+'}\\label{'+label+r'}\\'+'\n\\end{longtable}\n';path.write_text(s)
